#!/usr/bin/env python3
"""Build an adaptive Cipher-Suite-style VS Code workspace from repo-snapshot.json."""
from __future__ import annotations

import argparse
import html
import json
import shutil
from pathlib import Path

MAX_SNAPSHOT_BYTES = 8_000_000


def load_snapshot(path: Path) -> dict:
    if not path.exists() or path.stat().st_size > MAX_SNAPSHOT_BYTES:
        raise SystemExit("snapshot missing or too large")
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict) or not isinstance(value.get("repo"), dict):
        raise SystemExit("invalid snapshot")
    return value


def write_site(snapshot: dict, output: Path) -> None:
    repo = snapshot["repo"]
    rid = str(repo.get("id", "repository"))
    full = str(repo.get("full_name", rid))
    payload = json.dumps(snapshot, separators=(",", ":")).replace("</", "<\\/")
    output.mkdir(parents=True, exist_ok=True)
    (output / ".nojekyll").write_text("", encoding="utf-8")
    (output / "repo-snapshot.json").write_text(json.dumps(snapshot, indent=2) + "\n", encoding="utf-8")
    (output / "manifest.webmanifest").write_text(json.dumps({
        "name": f"{full} Workspace", "short_name": rid[:30], "start_url": "./", "scope": "./",
        "display": "standalone", "background_color": "#1e1e1e", "theme_color": "#1e1e1e"
    }, indent=2) + "\n", encoding="utf-8")

    template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#1e1e1e"><link rel="manifest" href="manifest.webmanifest"><title>__TITLE__ · Workspace</title>
<style>
:root{--bg:#1e1e1e;--editor:#1e1e1e;--title:#181818;--activity:#181818;--side:#252526;--side2:#2a2d2e;--line:#333;--text:#d4d4d4;--muted:#8f8f8f;--blue:#007acc;--green:#4ec9b0;--yellow:#dcdcaa;--orange:#ce9178;--red:#f48771;--purple:#c586c0;--cyan:#9cdcfe;--folder:#dcb67a}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font:13px/1.45 "Segoe UI Variable","Segoe UI",Arial,sans-serif}body{overflow-x:hidden}a{color:#4fc1ff;text-decoration:none}button{font:inherit}.app-shell{display:grid;grid-template-columns:48px 245px minmax(0,1fr);grid-template-rows:35px minmax(calc(100vh - 35px),auto);grid-template-areas:"title title title" "activity sidebar editor";min-height:100vh}.titlebar{grid-area:title;height:35px;background:var(--title);border-bottom:1px solid #2b2b2b;display:flex;align-items:center;padding:0 10px;gap:10px;position:sticky;top:0;z-index:50}.titlebar strong{font-size:12px;color:#fff}.title-muted,.title-status{font-size:11px;color:#858585}.title-status{margin-left:auto;max-width:45vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.app-mark{color:#23a8f2;font-size:17px}.icon-btn{border:0;background:transparent;color:#ccc;padding:2px 6px;font-size:18px;cursor:pointer}.mobile-only{display:none}.activitybar{grid-area:activity;background:var(--activity);border-right:1px solid #2b2b2b;display:flex;flex-direction:column;align-items:center;position:sticky;top:35px;height:calc(100vh - 35px);z-index:30}.activity{width:48px;height:48px;border:0;background:transparent;color:#858585;font:20px/1 Consolas,monospace;display:grid;place-items:center;cursor:pointer;border-left:2px solid transparent;text-decoration:none}.activity:hover,.activity.active{color:#fff}.activity.active{border-left-color:#fff;background:#202020}.activity-spacer{flex:1}.sidebar{grid-area:sidebar;background:var(--side);border-right:1px solid #2b2b2b;min-width:0;position:sticky;top:35px;height:calc(100vh - 35px);overflow:auto;z-index:25}.sidebar-head{height:35px;display:flex;align-items:center;padding:0 14px;font-size:11px;color:#bbb;letter-spacing:.05em}.repo-name{height:26px;padding:3px 8px;color:#eee;font-size:11px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tree-section{border-top:1px solid #303030}.tree-caption{padding:6px 8px 3px;color:#aaa;font-size:10px;font-weight:700}.tree-folder,.tree-item{width:100%;min-height:25px;border:0;background:transparent;color:#ccc;text-align:left;display:flex;align-items:center;gap:5px;padding:3px 7px;cursor:pointer;white-space:nowrap}.tree-item{padding-left:20px;font-size:12px}.tree-folder:hover,.tree-item:hover,.tree-item.active{background:var(--side2);color:#fff}.tree-item span{overflow:hidden;text-overflow:ellipsis}.folder-icon{color:var(--folder)}.children{padding-left:12px}.hidden{display:none}.editor{grid-area:editor;min-width:0;background:var(--editor);padding-bottom:23px;position:relative}.tabbar{height:35px;background:#181818;border-bottom:1px solid #252525;display:flex;align-items:stretch;position:sticky;top:35px;z-index:20}.editor-tab{min-width:145px;max-width:260px;background:var(--editor);border-right:1px solid #252525;border-top:1px solid var(--blue);display:flex;align-items:center;gap:7px;padding:0 10px;font-size:12px;color:#ddd}.breadcrumbs{height:28px;display:flex;align-items:center;padding:0 14px;color:#858585;font:11px Consolas,monospace;border-bottom:1px solid #242424;position:sticky;top:70px;background:var(--editor);z-index:19;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.toolbar{display:flex;gap:7px;align-items:center;padding:8px 14px;border-bottom:1px solid #252525;background:#1b1b1b;position:sticky;top:98px;z-index:18}.toolbar a,.toolbar button{background:#252526;border:1px solid #3a3a3a;color:#ccc;padding:5px 8px;cursor:pointer}.content{padding:18px 22px 44px;min-height:calc(100vh - 150px);overflow:auto}.welcome{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;max-width:1050px}.kicker{font:10px Consolas,monospace;color:var(--green);letter-spacing:.08em}.welcome h1{font-size:27px;font-weight:500;color:#fff;margin:5px 0}.muted{color:var(--muted)}.actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.actions a{background:#252526;border:1px solid #3a3a3a;color:#ccc;padding:6px 9px}.section-caption{margin:18px 0 8px;color:var(--purple);font:10px Consolas,monospace;letter-spacing:.08em}.status-grid,.folder-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:7px;max-width:1050px}.stat,.folder-card{background:#232323;border:1px solid #303030;padding:10px 11px}.stat b{display:block;color:#4fc1ff;font:18px Consolas,monospace}.stat:nth-child(2n) b{color:var(--green)}.stat:nth-child(3n) b{color:var(--yellow)}.stat:nth-child(4n) b{color:var(--purple)}.stat span{font-size:10px;color:#858585}.folder-card{display:grid;grid-template-columns:34px 1fr;gap:8px;text-align:left;color:#ddd;cursor:pointer}.folder-card:hover{background:#292929}.folder-card b{color:var(--cyan);font-weight:500}.big-folder{font-size:24px}.data-list{max-width:1150px;border:1px solid #2d2d2d}.row{display:grid;grid-template-columns:minmax(160px,1.2fr) minmax(220px,2fr) auto;gap:14px;align-items:center;padding:8px;border-top:1px solid #2a2a2a}.row:first-child{border-top:0}.row:hover{background:#252526}.row b{color:#9cdcfe;font-weight:500}.row:nth-child(3n+2) b{color:#dcdcaa}.row:nth-child(3n) b{color:#c586c0}.row-desc{color:#999;font-size:11px;overflow:hidden}.tags{display:flex;gap:4px;flex-wrap:wrap}.tag{font:9px Consolas,monospace;padding:2px 5px;border:1px solid #454545;color:#aaa}.repo-tree{max-width:1100px;border:1px solid #303030;background:#202020;padding:6px}.repo-tree .tree-folder,.repo-tree .tree-item{font-family:Consolas,monospace}.code-head{display:flex;gap:8px;align-items:center;margin-bottom:8px}.code-head strong{color:#9cdcfe}.code-head a{margin-left:auto}pre{margin:0;white-space:pre;overflow:auto;background:#181818;border:1px solid #333;padding:14px;min-height:55vh;font:13px/1.5 Consolas,monospace;color:#d4d4d4}.empty{color:#777;padding:16px 8px}.statusbar{position:absolute;bottom:0;left:0;right:0;height:23px;background:#007acc;color:#fff;display:flex;align-items:center;gap:14px;padding:0 8px;font-size:10px;white-space:nowrap;overflow:hidden}.statusbar span:nth-child(2){flex:1;overflow:hidden;text-overflow:ellipsis}
@media(max-width:850px){.app-shell{grid-template-columns:42px minmax(0,1fr);grid-template-areas:"title title" "activity editor"}.activitybar,.activity{width:42px}.sidebar{display:none;position:fixed;left:42px;top:35px;width:min(290px,calc(100vw - 42px));height:calc(100vh - 35px);box-shadow:5px 0 18px #0008;z-index:45}.sidebar.open{display:block}.mobile-only{display:inline-grid}.title-muted{display:none}.content{padding:14px 11px 40px}.welcome{grid-template-columns:1fr}.actions{justify-content:flex-start}.row{grid-template-columns:1fr;gap:3px}.status-grid{grid-template-columns:repeat(2,1fr)}}
</style></head><body>
<div class="app-shell"><header class="titlebar"><button id="menu" class="icon-btn mobile-only">☰</button><span class="app-mark">◈</span><strong>__TITLE__</strong><span class="title-muted">Repository Workspace</span><span id="titleStatus" class="title-status"></span></header>
<aside id="activity" class="activitybar"></aside><aside id="sidebar" class="sidebar"><div class="sidebar-head">EXPLORER</div><div class="repo-name">⌄ __REPO__</div><div id="workspaceNav"></div><div class="tree-section"><div class="tree-caption">REPOSITORY</div><div id="tree"></div></div></aside>
<main class="editor"><div class="tabbar"><div class="editor-tab"><span id="tabIcon">▰</span><span id="tabName">overview.md</span></div></div><div id="crumb" class="breadcrumbs"></div><div class="toolbar"><a href="__GITHUB__" target="_blank">GitHub</a><a href="__GITHUB__/actions" target="_blank">Actions</a><a href="https://kaibuzz0.github.io/Git-hub-command-site/">Command Center</a></div><section id="main" class="content"></section><footer class="statusbar"><span>◉ connected</span><span id="statusPath">__REPO__</span><span id="statusCommit"></span><span>UTF-8</span></footer></main></div>
<script id="snapshot" type="application/json">__SNAPSHOT__</script>
<script>
const S=JSON.parse(document.getElementById('snapshot').textContent),R=S.repo||{},T=S.repository_tree||{};
const $=s=>document.querySelector(s), main=$('#main'), tree=$('#tree'), side=$('#sidebar');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const collections=[['tools','⚙','Tools'],['toolsets','◫','Toolsets'],['cases','◌','Cases'],['opportunities','$','Opportunities'],['intelligence','⌁','Intelligence'],['sources','◎','Sources'],['evidence','◇','Evidence'],['prompts','⌘','Prompts'],['activity','⇄','Activity']];
function present(key){const v=S[key];return Array.isArray(v)?v.length>0:(v&&typeof v==='object'&&Object.keys(v).length>0)}
function setHead(name,icon,path){$('#tabName').textContent=name;$('#tabIcon').textContent=icon;$('#crumb').textContent=`${R.full_name||R.id} / ${path||name}`;$('#statusPath').textContent=path||name}
function itemName(x){return x?.name||x?.title||x?.id||x?.type||'item'} function itemDesc(x){return x?.description||x?.summary||x?.purpose||x?.status||x?.url||''}
function tags(x){return Object.entries(x||{}).filter(([k,v])=>['status','type','category','priority','maturity','severity','state'].includes(k)&&['string','number','boolean'].includes(typeof v)).slice(0,4).map(([,v])=>`<span class="tag">${esc(v)}</span>`).join('')}
function renderCollection(key,label,icon){setHead(label.toLowerCase()+'.json',icon,label.toLowerCase());let raw=S[key], rows=Array.isArray(raw)?raw:Object.entries(raw||{}).map(([name,value])=>typeof value==='object'?{name,...value}:{name,value});main.innerHTML=`<div class="welcome"><div><div class="kicker">STRUCTURED REPOSITORY DATA</div><h1>${esc(label)}</h1><p class="muted">Generated from this repository's validated command-site snapshot.</p></div></div><div class="section-caption">${rows.length} ITEMS</div><div class="data-list">${rows.length?rows.map(x=>`<div class="row"><div><b>${esc(itemName(x))}</b></div><div class="row-desc">${esc(itemDesc(x))}</div><div class="tags">${tags(x)}</div></div>`).join(''):'<div class="empty">No items.</div>'}</div>`}
function overview(){setHead('overview.md','▰','overview');let stats=S.stats||{}, cards=[['files',T.total_files||stats.tracked_files||0],['folders',T.total_directories||0],['tools',(S.tools||[]).length],['cases',(S.cases||[]).length],['activity',(S.activity||[]).length],['workflows',stats.workflow_files||0]];let rich=collections.filter(([k])=>present(k));main.innerHTML=`<div class="welcome"><div><div class="kicker">CONNECTED REPOSITORY</div><h1>${esc(R.full_name||R.id)}</h1><p>${esc(R.description||'Generated repository workspace powered by the central GitHub Command Site.')}</p></div><div class="actions"><a href="${esc(R.url)}" target="_blank">GitHub</a><a href="https://vscode.dev/github/${esc(R.full_name)}" target="_blank">Full VS Code</a></div></div><div class="section-caption">WORKSPACE STATUS</div><div class="status-grid">${cards.map(([a,b])=>`<div class="stat"><b>${esc(b)}</b><span>${esc(a)}</span></div>`).join('')}</div>${rich.length?`<div class="section-caption">AVAILABLE WORKSPACE DATA</div><div class="folder-grid">${rich.map(([k,i,l])=>`<button class="folder-card" data-view="${k}"><span class="big-folder">📂</span><span><b>${esc(l)}</b><small>${Array.isArray(S[k])?S[k].length:Object.keys(S[k]||{}).length} records</small></span></button>`).join('')}</div>`:''}`;bindViews()}
function rawUrl(path){let [o,r]=(R.full_name||'').split('/');return `https://raw.githubusercontent.com/${o}/${r}/${S.source_commit}/${path.split('/').map(encodeURIComponent).join('/')}`}
function gitUrl(path){return `${R.url}/blob/${S.source_commit}/${path.split('/').map(encodeURIComponent).join('/')}`}
const textExt=new Set(['.py','.js','.ts','.tsx','.jsx','.json','.md','.txt','.yml','.yaml','.html','.css','.scss','.sh','.toml','.ini','.cfg','.xml','.csv','.sql','.sol','.rs','.go','.java','.c','.h','.cpp','.hpp','.cs','.rb','.php','.lua','.r']);
async function openFile(path){setHead(path.split('/').pop(),'◇',path);main.innerHTML=`<p class="muted">Loading exact snapshot file…</p>`;let name=path.split('/').pop().toLowerCase(),ext=path.includes('.')?'.'+path.split('.').pop().toLowerCase():'';if(!textExt.has(ext)&&!['readme','license','dockerfile','makefile'].some(x=>name.startsWith(x))){main.innerHTML=`<p>This file is not previewed inline.</p><div class="actions"><a href="${gitUrl(path)}">Open on GitHub</a></div>`;return}try{let r=await fetch(rawUrl(path));if(!r.ok)throw Error(r.status);let text=await r.text();if(text.length>524288)throw Error('file exceeds 512 KB preview limit');main.innerHTML=`<div class="code-head"><strong>${esc(path)}</strong><a href="${gitUrl(path)}" target="_blank">GitHub ↗</a></div><pre>${esc(text)}</pre>`}catch(e){main.innerHTML=`<p>Preview unavailable: ${esc(e.message)}</p><div class="actions"><a href="${gitUrl(path)}">Open on GitHub</a></div>`}}
function buildTree(){let root={d:{},f:[]};(T.files||[]).forEach(x=>{let p=x.path.split('/'),n=root;for(let i=0;i<p.length-1;i++)n=n.d[p[i]]||(n.d[p[i]]={d:{},f:[]});n.f.push({name:p.at(-1),path:x.path})});function render(n,el,depth=0){Object.keys(n.d).sort().forEach(name=>{let wrap=document.createElement('div'),b=document.createElement('button'),c=document.createElement('div');b.className='tree-folder';b.innerHTML=`<span>${depth?'▸':'⌄'}</span><span class="folder-icon">📂</span><span>${esc(name)}</span>`;c.className='children'+(depth?' hidden':'');b.onclick=()=>{c.classList.toggle('hidden');b.firstElementChild.textContent=c.classList.contains('hidden')?'▸':'⌄'};wrap.append(b,c);el.append(wrap);render(n.d[name],c,depth+1)});n.f.sort((a,b)=>a.name.localeCompare(b.name)).forEach(f=>{let b=document.createElement('button');b.className='tree-item';b.innerHTML=`◇ <span>${esc(f.name)}</span>`;b.onclick=()=>openFile(f.path);el.append(b)})}render(root,tree)}
function bindViews(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{let key=b.dataset.view, c=collections.find(x=>x[0]===key);renderCollection(key,c[2],c[1]);if(innerWidth<851)side.classList.remove('open')})}
function buildNav(){const activity=$('#activity'),nav=$('#workspaceNav');activity.innerHTML=`<button class="activity active" data-home title="Explorer">▣</button>`+collections.filter(([k])=>present(k)).map(([k,i,l])=>`<button class="activity" data-view="${k}" title="${l}">${i}</button>`).join('')+`<div class="activity-spacer"></div><a class="activity" href="${esc(R.url)}" target="_blank">⌂</a>`;nav.innerHTML=`<div class="tree-section"><div class="tree-caption">WORKSPACE</div><button class="tree-item active" data-home>⌂ <span>overview</span></button>${collections.filter(([k])=>present(k)).map(([k,i,l])=>`<button class="tree-item" data-view="${k}">${i} <span>${l.toLowerCase()}</span></button>`).join('')}</div>`;document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{overview();if(innerWidth<851)side.classList.remove('open')});bindViews()}
$('#menu').onclick=()=>side.classList.toggle('open');$('#titleStatus').textContent=`snapshot ${String(S.source_commit||'').slice(0,12)} · ${S.generated_at||''}`;$('#statusCommit').textContent=String(S.source_commit||'').slice(0,8);buildNav();buildTree();overview();
</script></body></html>'''
    page = (template.replace("__TITLE__", html.escape(full))
            .replace("__REPO__", html.escape(full.upper()))
            .replace("__GITHUB__", html.escape(str(repo.get("url", "#"))))
            .replace("__SNAPSHOT__", payload))
    (output / "index.html").write_text(page, encoding="utf-8")


def main() -> int:
    p = argparse.ArgumentParser()
    p.add_argument("--snapshot", default="repo-snapshot.json")
    p.add_argument("--output", default="repo-site")
    a = p.parse_args()
    out = Path(a.output)
    if out.exists():
        shutil.rmtree(out)
    write_site(load_snapshot(Path(a.snapshot)), out)
    print(out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
